describe('Promo Code Application', () => {
    beforeEach(() => {
        cy.visit('/checkout');
    });

    it('should apply a valid promo code and display the discounted total', () => {
        cy.get('#promo-code-input').type('SAVE20');
        cy.get('#apply-promo-button').click();
        cy.get('#discount-message').should('contain', 'Promo code applied successfully');
        cy.get('#total-amount').should('contain', '$80.00'); // Assuming original total was $100.00
    });

    it('should show an error message for an invalid promo code', () => {
        cy.get('#promo-code-input').type('INVALIDCODE');
        cy.get('#apply-promo-button').click();
        cy.get('#discount-message').should('contain', 'Invalid promo code');
        cy.get('#total-amount').should('contain', '$100.00'); // Original total remains unchanged
    });
});
